import numpy as np
from sklearn.tree import DecisionTreeRegressor

def gradient_boost(X={{X}}, y={{y}}, n_estimators={{n_estimators}}, lr={{lr}}, max_depth={{max_depth}}):
    pred = np.full_like(y, y.mean(), dtype=float)
    trees = []
    for _ in range(n_estimators):
        residual = y - pred
        tree = DecisionTreeRegressor(max_depth=max_depth)
        tree.fit(X, residual)
        pred += lr * tree.predict(X)
        trees.append(tree)
    return trees, y.mean()

def gb_predict(X, trees, base, lr):
    p = np.full(X.shape[0], base, dtype=float)
    for t in trees: p += lr * t.predict(X)
    return p
